export async function fetchUser(id: string): Promise<User> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await requestUser(id)
    } catch (error) {
      if (attempt >= 3) throw error
      await sleep(2 ** attempt * 100)
    }
  }
}
